using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int x, int y) { return a[x] < a[y]; });
    vector<bool> visited(n, false);
    long long swaps = 0;
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            int length = 0, j = i;
            while (!visited[j]) {
                visited[j] = true;
                j = order[j];
                length++;
            }
            swaps += length - 1;
        }
    }
    cout << swaps << "\n";

    return 0;
}

